-- Group cities are public geographic reference data. Keep their ZIP crosswalk private.
create table spotter_private.club_cities (
    id text primary key,
    name text not null,
    region text not null,
    country text not null
);

create table spotter_private.training_zip_cities (
    zip text primary key references spotter_private.zip_centroids(zip),
    city_id text not null references spotter_private.club_cities(id)
);
create index spotter_training_zip_cities_by_city on spotter_private.training_zip_cities(city_id);

alter table spotter_private.club_cities enable row level security;
alter table spotter_private.training_zip_cities enable row level security;
revoke all on spotter_private.club_cities, spotter_private.training_zip_cities from public, anon, authenticated;

alter table spotter_private.local_club_memberships
    drop constraint local_club_memberships_pkey,
    alter column training_zip drop not null,
    add column city_id text references spotter_private.club_cities(id),
    add constraint local_club_memberships_one_area check (num_nonnulls(city_id, training_zip) = 1);

create unique index spotter_local_club_unique_city_membership
    on spotter_private.local_club_memberships (member_id, club_id, city_id) where city_id is not null;
create unique index spotter_local_club_unique_zip_membership
    on spotter_private.local_club_memberships (member_id, club_id) where city_id is null;
create index spotter_local_club_memberships_by_city
    on spotter_private.local_club_memberships (city_id, club_id, member_id) where city_id is not null;

alter table spotter_private.local_club_posts
    alter column training_zip drop not null,
    add column city_id text references spotter_private.club_cities(id),
    add column hidden_at timestamptz,
    add constraint local_club_posts_one_area check (num_nonnulls(city_id, training_zip) = 1);

create index spotter_local_club_posts_city_feed on spotter_private.local_club_posts
    (city_id, club_id, created_at desc, id desc) where city_id is not null and deleted_at is null and hidden_at is null;

-- City membership is explicit and remains available under Joined Groups when the training ZIP changes.
create or replace function spotter_private.reset_clubs_when_training_zip_changes() returns trigger
language plpgsql set search_path = '' as $$
begin
    delete from spotter_private.local_club_memberships where member_id = new.user_id and city_id is null;
    return new;
end;
$$;

-- Members still see previously posted ZIP content only in their original ZIP's default board.
create function spotter_private.club_area(p_member uuid, p_city_id text)
returns table (city_id text, legacy_zip text)
language plpgsql stable set search_path = '' as $$
declare
    home_zip text;
    home_city text;
begin
    select profile.zip, mapping.city_id into home_zip, home_city
    from spotter_private.profiles profile
    left join spotter_private.training_zip_cities mapping on mapping.zip = profile.zip
    where profile.user_id = p_member;

    if p_city_id is not null and not exists (select 1 from spotter_private.club_cities city where city.id = p_city_id) then
        raise exception 'Choose a city from the available groups.' using errcode = '22023';
    end if;

    return query
    select coalesce(p_city_id, home_city),
        case when p_city_id is null or p_city_id = home_city then home_zip end;
end;
$$;

create function spotter_private.current_club_memberships(
    p_city_id text, p_legacy_zip text, p_member uuid default null, p_club text default null
) returns setof spotter_private.local_club_memberships
language sql stable set search_path = '' as $$
    select membership.* from spotter_private.local_club_memberships membership
    join spotter_private.profiles profile on profile.user_id = membership.member_id and profile.active
        and (membership.city_id is not null or profile.zip = membership.training_zip)
    join spotter_private.local_club_waivers waiver on waiver.member_id = membership.member_id
        and waiver.club_id = membership.club_id and waiver.version = spotter_private.current_club_waiver_version()
    where (membership.city_id = p_city_id or (p_city_id is null and membership.training_zip = p_legacy_zip))
        and (p_member is null or membership.member_id = p_member)
        and (p_club is null or membership.club_id = p_club)
        and spotter_private.profile_is_visible(membership.member_id);
$$;

create function spotter_private.require_club_membership(
    p_member uuid, p_club text, p_city_id text, p_legacy_zip text
) returns void
language plpgsql stable set search_path = '' as $$
begin
    if not exists (
        select 1 from spotter_private.current_club_memberships(p_city_id, p_legacy_zip, p_member, p_club)
    ) then
        raise exception 'Join this Spotter club first.' using errcode = '42501';
    end if;
end;
$$;

create function spotter_private.city_json(p_city spotter_private.club_cities) returns jsonb
language sql immutable strict set search_path = '' as $$
    select jsonb_build_object('id', p_city.id, 'name', p_city.name, 'region', p_city.region, 'country', p_city.country);
$$;

create function spotter_private.city_search_key(p_value text) returns text
language sql immutable strict set search_path = '' as $$
    select btrim(regexp_replace(lower(p_value), '[[:space:],]+', ' ', 'g'));
$$;

create function spotter_private.group_cities(p_query text) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
    actor uuid := spotter_private.active_account();
    query text := spotter_private.city_search_key(left(coalesce(p_query, ''), 100));
    home_city text;
begin
    select area.city_id into home_city from spotter_private.club_area(actor, null) area;
    return jsonb_build_object(
        'default_city', (select spotter_private.city_json(city) from spotter_private.club_cities city where city.id = home_city),
        'cities', coalesce((
            select jsonb_agg(candidate.data order by candidate.position, candidate.name, candidate.region, candidate.id)
            from (
                select spotter_private.city_json(city) as data, city.name, city.region, city.id,
                    case
                        when query = '' and city.id = home_city then 0
                        when spotter_private.city_search_key(city.name) = query then 0
                        when strpos(spotter_private.city_search_key(city.name), query) = 1 then 1
                        else 2
                    end as position
                from spotter_private.club_cities city
                where (query = '' and (
                    city.id = home_city or exists (
                        select 1 from spotter_private.local_club_memberships membership
                        where membership.member_id = actor and membership.city_id = city.id
                    )
                )) or (
                    query <> '' and strpos(spotter_private.city_search_key(city.name || ' ' || city.region || ' ' || city.country), query) > 0
                )
                order by position, city.name, city.region, city.id
                limit 30
            ) candidate
        ), '[]'::jsonb)
    );
end;
$$;

create function spotter_private.group_club_json(p_club text, p_count integer, p_joined boolean, p_waiver boolean)
returns jsonb language sql immutable set search_path = '' as $$
    select jsonb_build_object('id', p_club, 'member_count', p_count, 'joined', p_joined, 'waiver_accepted', p_waiver);
$$;

create function spotter_private.get_local_clubs(p_city_id text) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
    actor uuid := spotter_private.active_account();
    area record;
begin
    select * into area from spotter_private.club_area(actor, p_city_id);
    return (
        select jsonb_agg(spotter_private.group_club_json(
            club.id, coalesce(members.member_count, 0), coalesce(members.joined, false), waiver.member_id is not null
        ) order by club.position)
        from spotter_private.local_club_catalog club
        left join spotter_private.local_club_waivers waiver on waiver.member_id = actor
            and waiver.club_id = club.id and waiver.version = spotter_private.current_club_waiver_version()
        left join (
            select membership.club_id, count(*)::integer as member_count,
                bool_or(membership.member_id = actor) as joined
            from spotter_private.current_club_memberships(area.city_id, area.legacy_zip) membership
            where not community_private.actors_are_blocked(actor, membership.member_id)
            group by membership.club_id
        ) members on members.club_id = club.id
    );
end;
$$;

create function spotter_private.joined_city_clubs() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
    actor uuid := spotter_private.active_account();
begin
    return coalesce((
        select jsonb_agg(jsonb_build_object('city', spotter_private.city_json(city), 'club',
            spotter_private.group_club_json(club.id, counts.member_count, true, true))
            order by city.name, city.region, city.id, club.position)
        from spotter_private.local_club_memberships own
        join spotter_private.club_cities city on city.id = own.city_id
        join spotter_private.local_club_catalog club on club.id = own.club_id
        cross join lateral (
            select count(*)::integer as member_count, bool_or(membership.member_id = actor) as joined
            from spotter_private.current_club_memberships(own.city_id, null, null, own.club_id) membership
            where not community_private.actors_are_blocked(actor, membership.member_id)
        ) counts
        where own.member_id = actor and counts.joined
    ), '[]'::jsonb);
end;
$$;

create function spotter_private.set_local_club_membership(p_club text, p_joined boolean, p_city_id text) returns boolean
language plpgsql security definer set search_path = '' as $$
declare
    actor uuid := spotter_private.active_account();
    area record;
begin
    if p_joined is null or not exists (select 1 from spotter_private.local_club_catalog where id = p_club) then
        raise exception 'Choose a Spotter club and whether to join.' using errcode = '22023';
    end if;

    perform spotter_private.lock_club_actor_zip(actor);
    select * into area from spotter_private.club_area(actor, p_city_id);
    if p_joined then
        if not exists (select 1 from spotter_private.local_club_waivers where member_id = actor and club_id = p_club
            and version = spotter_private.current_club_waiver_version()) then
            raise exception 'Accept the current waiver before joining this club.' using errcode = '42501';
        end if;
        insert into spotter_private.local_club_memberships (member_id, club_id, city_id, training_zip)
        values (actor, p_club, area.city_id, case when area.city_id is null then area.legacy_zip end)
        on conflict do nothing;
    else
        delete from spotter_private.local_club_memberships membership
        where membership.member_id = actor and membership.club_id = p_club
            and (membership.city_id = area.city_id or (area.city_id is null and membership.training_zip = area.legacy_zip));
    end if;
    return true;
end;
$$;

create function spotter_private.accept_local_club_waiver_and_join(p_club text, p_version text, p_city_id text) returns boolean
language plpgsql security definer set search_path = '' as $$
declare
    actor uuid := spotter_private.active_account();
begin
    if p_version is distinct from spotter_private.current_club_waiver_version()
        or not exists (select 1 from spotter_private.local_club_catalog where id = p_club) then
        raise exception 'Choose a club and accept its current waiver.' using errcode = '22023';
    end if;
    perform spotter_private.lock_club_actor_zip(actor);
    insert into spotter_private.local_club_waivers (member_id, club_id, version)
    values (actor, p_club, p_version) on conflict (member_id, club_id, version) do nothing;
    return spotter_private.set_local_club_membership(p_club, true, p_city_id);
end;
$$;

create function spotter_private.post_in_club_area(
    p_post spotter_private.local_club_posts, p_city_id text, p_legacy_zip text
) returns boolean language sql immutable set search_path = '' as $$
    select coalesce(p_post.city_id = p_city_id, false) or coalesce(p_post.training_zip = p_legacy_zip, false);
$$;

create function spotter_private.club_post_visible_in_area(
    p_viewer uuid, p_post spotter_private.local_club_posts, p_city_id text, p_legacy_zip text
) returns boolean language sql stable set search_path = '' as $$
    select p_post.deleted_at is null and p_post.hidden_at is null
        and spotter_private.post_in_club_area(p_post, p_city_id, p_legacy_zip)
        and (p_post.training_zip is null or exists (
            select 1 from spotter_private.profiles author where author.user_id = p_post.author_id and author.zip = p_post.training_zip
        ))
        and exists (
            select 1 from spotter_private.current_club_memberships(p_city_id, p_legacy_zip, p_post.author_id, p_post.club_id)
        )
        and not community_private.actors_are_blocked(p_viewer, p_post.author_id)
        and community_private.viewer_can_see_content('spotter_club_post', p_post.id::text);
$$;

create or replace function spotter_private.club_post_visible(p_viewer uuid, p_post spotter_private.local_club_posts)
returns boolean language sql stable set search_path = '' as $$
    select spotter_private.club_post_visible_in_area(p_viewer, p_post, area.city_id, area.legacy_zip)
    from spotter_private.club_area(p_viewer, null) area;
$$;

create function spotter_private.list_local_club_posts(p_club text, p_city_id text) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
    actor uuid := spotter_private.active_account();
    area record;
begin
    select * into area from spotter_private.club_area(actor, p_city_id);
    perform spotter_private.require_club_membership(actor, p_club, area.city_id, area.legacy_zip);
    return coalesce((
        select jsonb_agg(jsonb_build_object(
            'id', post.id, 'author_name', post.author_name, 'body', post.body,
            'created_at', post.created_at, 'mine', post.author_id = actor
        ) order by post.created_at desc, post.id desc)
        from (
            select candidate.id, candidate.author_id, candidate.body, candidate.created_at,
                author.preferences ->> 'name' as author_name
            from spotter_private.local_club_posts candidate
            join spotter_private.profiles author on author.user_id = candidate.author_id
            where candidate.club_id = p_club and candidate.deleted_at is null and candidate.hidden_at is null
                and (candidate.city_id = area.city_id or candidate.training_zip = area.legacy_zip)
                and spotter_private.club_post_visible_in_area(actor, candidate, area.city_id, area.legacy_zip)
            order by candidate.created_at desc, candidate.id desc
            limit 40
        ) post
    ), '[]'::jsonb);
end;
$$;

create function spotter_private.post_to_local_club(p_club text, p_post_id uuid, p_body text, p_city_id text) returns boolean
language plpgsql security definer set search_path = '' as $$
declare
    actor uuid := spotter_private.active_account();
    cleaned text := spotter_private.clean_text(p_body, 1000);
    previous spotter_private.local_club_posts;
    area record;
begin
    if p_post_id is null or cleaned = '' then
        raise exception 'Enter a message to post to this club.' using errcode = '22023';
    end if;
    perform spotter_private.lock_club_actor_zip(actor);
    select * into area from spotter_private.club_area(actor, p_city_id);
    perform spotter_private.require_club_membership(actor, p_club, area.city_id, area.legacy_zip);
    select * into previous from spotter_private.local_club_posts where id = p_post_id;
    if found then
        if previous.author_id = actor and previous.club_id = p_club
            and spotter_private.post_in_club_area(previous, area.city_id, area.legacy_zip)
            and (previous.body = cleaned or previous.deleted_at is not null) then
            return true;
        end if;
        raise exception 'This message could not be saved.' using errcode = '22023';
    end if;
    if (select count(*) from spotter_private.local_club_posts
        where author_id = actor and created_at > clock_timestamp() - interval '1 minute') >= 20 then
        raise exception 'Please wait before sending another message.' using errcode = '22023';
    end if;
    insert into spotter_private.local_club_posts (id, author_id, club_id, city_id, training_zip, body)
    values (p_post_id, actor, p_club, area.city_id, case when area.city_id is null then area.legacy_zip end, cleaned)
    on conflict (id) do nothing;
    if not found then raise exception 'This message could not be saved.' using errcode = '22023'; end if;
    return true;
end;
$$;

create function spotter_private.delete_local_club_post(p_club text, p_post_id uuid, p_city_id text) returns boolean
language plpgsql security definer set search_path = '' as $$
declare
    actor uuid := spotter_private.active_account();
    area record;
begin
    perform spotter_private.lock_club_actor_zip(actor);
    select * into area from spotter_private.club_area(actor, p_city_id);
    perform spotter_private.require_club_membership(actor, p_club, area.city_id, area.legacy_zip);
    update spotter_private.local_club_posts post
    set body = null, deleted_at = coalesce(deleted_at, clock_timestamp())
    where id = p_post_id and club_id = p_club and author_id = actor
        and spotter_private.post_in_club_area(post, area.city_id, area.legacy_zip);
    return found;
end;
$$;

create function spotter_private.report_local_club_post(p_club text, p_post_id uuid, p_reason text, p_city_id text) returns boolean
language plpgsql security definer set search_path = '' as $$
declare
    actor uuid := spotter_private.active_account();
    clean_reason text := btrim(coalesce(p_reason, ''), E' \n\r\t');
    post spotter_private.local_club_posts;
    area record;
begin
    if char_length(clean_reason) not between 1 and 500 then
        raise exception 'Enter a report reason.' using errcode = '22023';
    end if;
    perform spotter_private.lock_club_actor_zip(actor);
    select * into area from spotter_private.club_area(actor, p_city_id);
    perform spotter_private.require_club_membership(actor, p_club, area.city_id, area.legacy_zip);
    perform pg_advisory_xact_lock(hashtextextended('community-report:' || actor::text, 0));
    select * into post from spotter_private.local_club_posts candidate
    where candidate.id = p_post_id and candidate.club_id = p_club and candidate.author_id <> actor
        and spotter_private.club_post_visible_in_area(actor, candidate, area.city_id, area.legacy_zip);
    if not found then
        raise exception 'This club message is unavailable.' using errcode = '42501';
    end if;
    if exists (select 1 from community_private.content_reports where reporter_id = actor
        and content_kind = 'spotter_club_post' and content_id = post.id::text) then return true; end if;
    if (select count(*) from community_private.content_reports where reporter_id = actor
        and created_at >= now() - interval '1 day') >= 30 then
        raise exception 'Daily community report limit reached.' using errcode = '22023';
    end if;
    insert into community_private.content_reports (
        reporter_id, member_id, content_kind, content_id, reason, details, content_excerpt
    ) values (actor, post.author_id, 'spotter_club_post', post.id::text, 'other', clean_reason, left(post.body, 500));
    return true;
end;
$$;

-- Preserve the exact signatures used by already-installed clients. Null selects the member's default city.
create or replace function spotter_private.get_local_clubs() returns jsonb
language sql stable set search_path = '' as $$ select spotter_private.get_local_clubs(null); $$;
create or replace function spotter_private.set_local_club_membership(p_club text, p_joined boolean) returns boolean
language sql set search_path = '' as $$ select spotter_private.set_local_club_membership(p_club, p_joined, null); $$;
create or replace function spotter_private.accept_local_club_waiver_and_join(p_club text, p_version text) returns boolean
language sql set search_path = '' as $$ select spotter_private.accept_local_club_waiver_and_join(p_club, p_version, null); $$;
create or replace function spotter_private.list_local_club_posts(p_club text) returns jsonb
language sql stable set search_path = '' as $$ select spotter_private.list_local_club_posts(p_club, null); $$;
create or replace function spotter_private.post_to_local_club(p_club text, p_post_id uuid, p_body text) returns boolean
language sql set search_path = '' as $$ select spotter_private.post_to_local_club(p_club, p_post_id, p_body, null); $$;
create or replace function spotter_private.delete_local_club_post(p_club text, p_post_id uuid) returns boolean
language sql set search_path = '' as $$ select spotter_private.delete_local_club_post(p_club, p_post_id, null); $$;
create or replace function spotter_private.report_local_club_post(p_club text, p_post_id uuid, p_reason text) returns boolean
language sql set search_path = '' as $$ select spotter_private.report_local_club_post(p_club, p_post_id, p_reason, null); $$;

