create function public.spotter_set_club_membership(p_club text, p_joined boolean, p_city_id text) returns boolean
language sql set search_path = '' as $$ select spotter_private.set_local_club_membership(p_club, p_joined, p_city_id); $$;
create function public.spotter_accept_club_waiver_and_join(p_club text, p_version text, p_city_id text) returns boolean
