language sql set search_path = '' as $$ select spotter_private.report_local_club_post(p_club, p_post_id, p_reason, p_city_id); $$;

revoke execute on function spotter_private.club_area(uuid, text),
    spotter_private.current_club_memberships(text, text, uuid, text),
    spotter_private.require_club_membership(uuid, text, text, text),
    spotter_private.city_json(spotter_private.club_cities), spotter_private.city_search_key(text),
    spotter_private.group_club_json(text, integer, boolean, boolean),
    spotter_private.post_in_club_area(spotter_private.local_club_posts, text, text),
    spotter_private.club_post_visible_in_area(uuid, spotter_private.local_club_posts, text, text)
from public, anon, authenticated;

