    spotter_private.get_local_clubs(text), spotter_private.set_local_club_membership(text, boolean, text),
    spotter_private.accept_local_club_waiver_and_join(text, text, text), spotter_private.list_local_club_posts(text, text),
    spotter_private.post_to_local_club(text, uuid, text, text), spotter_private.delete_local_club_post(text, uuid, text),
    spotter_private.report_local_club_post(text, uuid, text, text),
    public.spotter_group_cities(text), public.spotter_joined_city_clubs(), public.spotter_local_clubs(text),
    public.spotter_set_club_membership(text, boolean, text), public.spotter_accept_club_waiver_and_join(text, text, text),
    public.spotter_club_posts(text, text), public.spotter_post_to_club(text, uuid, text, text),
    public.spotter_delete_club_post(text, uuid, text), public.spotter_report_club_post(text, uuid, text, text)
from public, anon, authenticated;

grant execute on function spotter_private.group_cities(text), spotter_private.joined_city_clubs(),
